const base = process.argv[2];
const paths = ['/prices/SKU-1?currency=EUR&currency=USD', '/prices/SKU-1?currency[]=USD', '/prices/SKU-1?currency=',
  '/prices/SKU-1?currency', '/prices/SKU-1/', '/prices/%ZZ', '/prices/SKU%2F1', '/prices/a+b?currency=a+b',
  '/prices/SKU-1?currency=%45UR', '/prices/SKU-1?currency=%ZZ', '/prices/SKU-1?currency[a]=1', '/prices/',
  '/prices/SKU-1?currency=US%', '/prices/SKU-1?currency=EUR;x=1', '/prices/SKU-1?a=1&&currency=USD',
  '/PRICES/SKU-1', '/prices/SKU-1?currency.x=1', '/prices//SKU-1', '/prices/SKU-1?Currency=USD',
  '/prices/SKU-1?currency=EUR&currency=', '/prices/SKU-1?currency=&currency=EUR', '/prices/SKU-1?currency=EUR&currency[]=USD',
  '/prices/SKU-1?currency[]=USD&currency=EUR', '/prices/SKU-1?currency[0]=USD', '/prices/SKU-1?currency%5B%5D=USD',
  '/prices/SKU-1?%63urrency=USD', '/prices/%', '/prices/SKU-1?currency=%E2%82%AC', '/prices/SKU-1?=x&currency=USD',
  '/prices/SKU-1?currency=a=b', '/prices/SKU-1?currency=a%26b', '/prices/%C0', '/prices/SKU-1;x', '/prices/SKU-1.json'];
for (const p of paths) {
  for (const m of ['GET']) {
    const r = await fetch(base + p, { method: m });
    const t = await r.text();
    console.log(m, p, r.status, r.headers.get('content-type'), t.slice(0, 120).replace(/\n/g, ' '));
  }
}
for (const m of ['HEAD', 'POST', 'OPTIONS']) {
  const r = await fetch(base + '/prices/SKU-1', { method: m });
  console.log(m, r.status, r.headers.get('content-type'), r.headers.get('allow'), (await r.text()).slice(0, 80).replace(/\n/g, ' '));
}
